        return 1
    return n * factorial_1776(n - 1)

print(factorial_1776(3))

def solve_1777():
    a = 22
    b = 4
    return (a // b) + (a % b)

print(solve_1777())

def loop_1778():
    total = 0
    for i in range(1, 7):
        if i == 4:
            continue
        total += i
    return total

print(loop_1778())

def stream_1781():
    items = [2, 4, 6]
    return sum(x * 4 for x in items)

print(stream_1781())

